<?php
require __DIR__.'/app/bootstrap.php';$u=require_login();$orderId=(int)($_GET['order_id']??$_POST['order_id']??0);$o=operations_row('SELECT * FROM store_orders WHERE id=? AND buyer_user_id=?',[$orderId,(int)$u['id']]);if(!$o){http_response_code(404);exit('Order not found.');}$msg=$err=null;if($_SERVER['REQUEST_METHOD']==='POST')try{csrf_check();operations_open_dispute($orderId,(int)$u['id'],(string)$_POST['reason'],(string)$_POST['description'],(float)($_POST['amount']??$o['grand_total']));$msg='Dispute opened. ShahkotPK support will review it.';}catch(Throwable $e){$err=$e->getMessage();}$rows=operations_rows('SELECT * FROM commerce_disputes WHERE order_id=? ORDER BY id DESC',[$orderId]);
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Order Dispute</title><link rel="stylesheet" href="/assets/shahkotpk-userdash-1.7.0.css"><link rel="stylesheet" href="/assets/operations-3.6.0.css"></head><body class="dashboard-page"><div class="dash-shell"><div class="dash-topbar"><a class="dash-back" href="/order.php?id=<?=e($orderId)?>">← Order</a></div><section class="dash-hero"><div><span class="dash-badge">BUYER PROTECTION</span><h1>Dispute <?=e($o['order_number'])?></h1><p>Use this workflow for delivery, condition, digital access or payment problems.</p></div></section><?php if($msg):?><div class="success"><?=e($msg)?></div><?php endif;?><?php if($err):?><div class="error"><?=e($err)?></div><?php endif;?><section class="dash-card"><form method="post" class="ops-form"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="order_id" value="<?=e($orderId)?>"><select name="reason"><option value="not_received">Not received</option><option value="not_as_described">Not as described</option><option value="damaged">Damaged</option><option value="digital_access">Digital access issue</option><option value="payment">Payment issue</option><option value="other">Other</option></select><input name="amount" type="number" step="0.01" max="<?=e($o['grand_total'])?>" value="<?=e($o['grand_total'])?>"><textarea class="wide" name="description" required placeholder="Explain the problem and what resolution you need"></textarea><button class="btn">Open Dispute</button></form></section><section class="dash-card"><h2>Case History</h2><?php foreach($rows as $r):?><div class="ops-card"><b><?=e($r['dispute_number'])?></b> <span class="ops-badge"><?=e($r['status'])?></span><p><?=nl2br(e($r['description']))?></p><?php if($r['resolution_notes']):?><p><b>Resolution:</b> <?=e($r['resolution_notes'])?></p><?php endif;?></div><?php endforeach;?></section></div></body></html>
